{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Genera deployment audit log",
  "description": "Everything a human deployment rep needs to know before trusting the config: what you assumed, what's missing, what conflicts, and what the customer asked for that the Ramp API cannot do. An empty audit log on a messy packet is a red flag, not an achievement.",
  "type": "object",
  "required": ["client_id", "assumptions_made", "missing_information_flags", "conflicts", "unsupported_api_requests"],
  "additionalProperties": false,
  "properties": {
    "client_id": { "type": "string" },

    "assumptions_made": {
      "type": "array",
      "description": "Judgment calls you made to produce a complete config. Each one is something a human could veto.",
      "items": {
        "type": "object",
        "required": ["assumption", "source", "impact_if_wrong"],
        "additionalProperties": false,
        "properties": {
          "assumption": { "type": "string" },
          "source": { "type": "string", "description": "file + line/quote that forced the assumption" },
          "impact_if_wrong": { "type": "string" }
        }
      }
    },

    "missing_information_flags": {
      "type": "array",
      "description": "Things you needed and did not have. Phrase each as the question you'd ask the customer.",
      "items": {
        "type": "object",
        "required": ["question", "blocking"],
        "additionalProperties": false,
        "properties": {
          "question": { "type": "string" },
          "affected_config": { "type": "string", "description": "which config section is provisional until answered" },
          "blocking": { "type": "boolean", "description": "true if the config should not be applied before this is answered" }
        }
      }
    },

    "conflicts": {
      "type": "array",
      "description": "Places where the customer's own sources disagree. Do not silently pick a winner — record both, say which you provisionally encoded and why, and flag for human resolution.",
      "items": {
        "type": "object",
        "required": ["description", "source_a", "source_b", "provisional_resolution"],
        "additionalProperties": false,
        "properties": {
          "description": { "type": "string" },
          "source_a": { "type": "string", "description": "file + quote" },
          "source_b": { "type": "string", "description": "file + quote" },
          "provisional_resolution": { "type": "string", "description": "what you encoded and why — or 'none, blocking'" }
        }
      }
    },

    "unsupported_api_requests": {
      "type": "array",
      "description": "Customer asks the Ramp Developer API cannot fulfill. Cite evidence — the endpoint you checked or the docs page — not vibes. Getting these right (including NOT listing things the API does support) is graded.",
      "items": {
        "type": "object",
        "required": ["requested_feature", "reason_unsupported", "evidence", "proposed_manual_workaround"],
        "additionalProperties": false,
        "properties": {
          "requested_feature": { "type": "string" },
          "reason_unsupported": { "type": "string" },
          "evidence": { "type": "string", "description": "e.g. 'docs.ramp.com: /entities exposes GET only' — what you checked, not what you guessed" },
          "proposed_manual_workaround": { "type": "string", "description": "how a deployment rep gets the customer the outcome anyway (in-app setup, process change, partial API mechanism)" }
        }
      }
    }
  }
}
=====CONFIG=====
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Genera → Ramp deployment configuration (desired state)",
  "description": "The desired-state configuration your pipeline produces for one customer. Field shapes intentionally mirror Ramp's Developer API create-request bodies where an API exists (see docs.ramp.com). Where no API exists to apply a section, the section still belongs here as desired state — and the gap belongs in your audit log.",
  "type": "object",
  "required": ["client_id", "generated_at", "entities", "departments", "users", "spend_programs", "limits", "approval_policies", "mcc_controls"],
  "additionalProperties": false,
  "properties": {
    "client_id": { "type": "string", "description": "e.g. client_a_acme_corp" },
    "generated_at": { "type": "string", "description": "ISO 8601 timestamp" },
    "base_currency": { "type": "string", "description": "ISO 4217 code all normalized amounts are stated in, e.g. USD" },

    "entities": {
      "type": "array",
      "description": "Legal entities spend is organized under. NOTE: check what the Ramp API lets you do with entities before assuming your pipeline can create them.",
      "items": {
        "type": "object",
        "required": ["name", "country", "currency", "status"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "country": { "type": "string", "description": "ISO 3166-1 alpha-2" },
          "currency": { "type": "string", "description": "ISO 4217" },
          "status": { "type": "string", "enum": ["existing", "requested"], "description": "existing = already present in the customer's Ramp instance; requested = customer wants it created" }
        }
      }
    },

    "departments": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "entity": { "type": "string", "description": "entities[].name this department belongs to, if stated" }
        }
      }
    },

    "locations": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["name"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "country": { "type": "string" }
        }
      }
    },

    "users": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["email", "first_name", "last_name", "role", "department"],
        "additionalProperties": false,
        "properties": {
          "email": { "type": "string" },
          "first_name": { "type": "string" },
          "last_name": { "type": "string" },
          "role": {
            "type": "string",
            "enum": ["BUSINESS_ADMIN", "BUSINESS_USER", "BUSINESS_BOOKKEEPER", "IT_ADMIN", "AUDITOR", "GUEST_USER"],
            "description": "Ramp invitable role. If a source document asks for a role outside this enum, that's a mapping decision — record it."
          },
          "department": { "type": "string", "description": "departments[].name" },
          "location": { "type": "string" },
          "direct_manager_email": { "type": ["string", "null"], "description": "null if unknown — and if unknown, say so in the audit log" },
          "notes": { "type": "string" }
        }
      }
    },

    "spend_programs": {
      "type": "array",
      "description": "Reusable spend templates (e.g. Software, Travel, Field Ops). Mirrors POST /spend-programs.",
      "items": {
        "type": "object",
        "required": ["display_name", "description", "permitted_spend_types", "spending_restrictions"],
        "additionalProperties": false,
        "properties": {
          "display_name": { "type": "string" },
          "description": { "type": "string" },
          "permitted_spend_types": {
            "type": "object",
            "required": ["primary_card_enabled", "reimbursements_enabled"],
            "additionalProperties": false,
            "properties": {
              "primary_card_enabled": { "type": "boolean" },
              "reimbursements_enabled": { "type": "boolean" }
            }
          },
          "issue_physical_card_if_needed": { "type": "boolean" },
          "spending_restrictions": { "$ref": "#/$defs/spending_restrictions" }
        }
      }
    },

    "limits": {
      "type": "array",
      "description": "Per-person or per-team spend limits (the objects cards draw from). Mirrors the Limits API create body.",
      "items": {
        "type": "object",
        "required": ["display_name", "assigned_to", "spending_restrictions"],
        "additionalProperties": false,
        "properties": {
          "display_name": { "type": "string" },
          "assigned_to": {
            "type": "object",
            "description": "Exactly one of user_email or group must be set.",
            "additionalProperties": false,
            "properties": {
              "user_email": { "type": "string" },
              "group": { "type": "string", "description": "a department name or a named cohort, e.g. 'Field Reps'" }
            }
          },
          "spend_program": { "type": "string", "description": "spend_programs[].display_name this limit is issued from, if any" },
          "spending_restrictions": { "$ref": "#/$defs/spending_restrictions" },
          "notes": { "type": "string" }
        }
      }
    },

    "approval_policies": {
      "type": "array",
      "description": "Approval chains as desired state. Before assuming your pipeline can apply these, check what the Ramp API supports — and record what you find.",
      "items": {
        "type": "object",
        "required": ["name", "applies_to", "tiers"],
        "additionalProperties": false,
        "properties": {
          "name": { "type": "string" },
          "applies_to": { "type": "string", "description": "what spend this policy governs (a department, spend program, or 'all')" },
          "tiers": {
            "type": "array",
            "items": {
              "type": "object",
              "required": ["threshold_usd_cents", "approver"],
              "additionalProperties": false,
              "properties": {
                "threshold_usd_cents": { "type": "integer", "description": "amounts at or above this require this approver; 0 = auto-approve tier" },
                "approver": { "type": "string", "description": "AUTO, DIRECT_MANAGER, or a role/person, e.g. 'VP Finance (dmarsh@acme.example)'" }
              }
            }
          },
          "source": { "type": "string", "description": "which document/line this policy came from — matters when sources conflict" }
        }
      }
    },

    "mcc_controls": {
      "type": "array",
      "description": "Category controls, stated the way Ramp can enforce them. Note carefully which direction (allow vs block) and which vocabulary (Ramp category codes vs raw MCC codes) the API actually accepts.",
      "items": {
        "type": "object",
        "required": ["applies_to", "mechanism"],
        "additionalProperties": false,
        "properties": {
          "applies_to": { "type": "string", "description": "limit or spend_program display_name" },
          "mechanism": {
            "type": "string",
            "enum": ["allowed_categories", "blocked_categories", "blocked_mcc_codes", "allowed_vendors", "blocked_vendors"],
            "description": "the actual API field you would use"
          },
          "values": { "type": "array", "items": { "type": ["string", "integer"] } },
          "translation_notes": { "type": "string", "description": "how you got from what the customer said to this mechanism — e.g. MCC allowlist → category allowlist mapping" }
        }
      }
    }
  },

  "$defs": {
    "spending_restrictions": {
      "type": "object",
      "required": ["limit_amount_cents", "currency", "interval"],
      "additionalProperties": false,
      "properties": {
        "limit_amount_cents": { "type": "integer", "description": "smallest currency unit, per Ramp convention" },
        "currency": { "type": "string", "description": "ISO 4217. If you normalized from another currency, record the source amount and rate in the audit log." },
        "interval": {
          "type": "string",
          "enum": ["DAILY", "WEEKLY", "MONTHLY", "QUARTERLY", "YEARLY", "ANNUAL", "TOTAL"],
          "description": "Ramp limit interval"
        },
        "transaction_amount_limit_cents": { "type": ["integer", "null"] },
        "lock_date": { "type": ["string", "null"], "description": "ISO 8601 date to auto-lock (useful for temporary cards)" },
        "allowed_categories": { "type": "array", "items": { "type": "string" } },
        "blocked_categories": { "type": "array", "items": { "type": "string" } },
        "blocked_mcc_codes": { "type": "array", "items": { "type": ["string", "integer"] } },
        "allowed_vendors": { "type": "array", "items": { "type": "string" } },
        "blocked_vendors": { "type": "array", "items": { "type": "string" } }
      }
    }
  }
}

